contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount >= 1 ether);
        require(address(this).balance >= depositAmount);
        c.Deposit{value: depositAmount}();
        uint balBefore = c.balances(address(this));
        require(balBefore == depositAmount);

        // Try to withdraw more than the balance: must revert, balance unchanged.
        bool reverted;
        try c.CashOut(withdrawAmount) { reverted = false; } catch { reverted = true; }

        uint balAfter = c.balances(address(this));
        bool overReverted = reverted;
        uint balAfterOver = balAfter;

        // Withdrawing exactly the remaining balance must succeed and zero it.
        if (withdrawAmount > balBefore) {
            c.CashOut(balBefore);
            assert(overReverted && balAfterOver == balBefore && c.balances(address(this)) == 0);
        } else {
            // withdrawAmount <= balance: the first call should not revert,
            // and must reduce the balance by exactly withdrawAmount.
            c.CashOut(balBefore - balAfter);
            assert(!overReverted && balAfterOver <= balBefore && c.balances(address(this)) >= 0);
        }
    }
    receive() external payable {}
}

